CREATE TABLE "server" ("updated_at" INTEGER NOT NULL DEFAULT 0, "rev" INTEGER NOT NULL DEFAULT 0, "id" TEXT NOT NULL, "name" TEXT NOT NULL, "auto_connect" INTEGER NOT NULL DEFAULT 1 CHECK ("auto_connect" IN (0, 1)), "system_type" TEXT NULL, "ssh_ip" TEXT NULL, "ssh_port" INTEGER NULL, "ssh_user" TEXT NULL, "ssh_pwd" TEXT NULL, "ssh_key_id" TEXT NULL REFERENCES private_key (id) ON DELETE SET NULL, "ssh_key_path" TEXT NULL, "ssh_alter_url" TEXT NULL, "ssh_proxy_command" TEXT NULL, "ssh_file_transport" TEXT NULL, "ssh_allow_legacy_algorithms" INTEGER NOT NULL DEFAULT 0 CHECK ("ssh_allow_legacy_algorithms" IN (0, 1)), "preferred_transport" TEXT NULL, "ssh_enabled" INTEGER NOT NULL DEFAULT 1 CHECK ("ssh_enabled" IN (0, 1)), "monitor_enabled" INTEGER NOT NULL DEFAULT 1 CHECK ("monitor_enabled" IN (0, 1)), "is_local" INTEGER NOT NULL DEFAULT 0 CHECK ("is_local" IN (0, 1)), "monitor_addr" TEXT NULL, "monitor_user" TEXT NULL, "monitor_pwd" TEXT NULL, "monitor_cert_sha256" TEXT NULL, "monitor_allow_insecure" INTEGER NULL CHECK ("monitor_allow_insecure" IN (0, 1)), "wol_mac" TEXT NULL, "wol_ip" TEXT NULL, "wol_pwd" TEXT NULL, "bmc_addr" TEXT NULL, "bmc_cert_sha256" TEXT NULL, "bmc_cred_id" TEXT NULL REFERENCES bmc_credential (id) ON DELETE SET NULL, "prefer_temp_dev" TEXT NULL, "temp_is_celsius" INTEGER NOT NULL DEFAULT 1 CHECK ("temp_is_celsius" IN (0, 1)), "logo_url" TEXT NULL, "net_dev" TEXT NULL, "script_dir" TEXT NULL, "geo_lat" REAL NULL, "geo_lon" REAL NULL, "disk_counts_network" INTEGER NOT NULL DEFAULT 0 CHECK ("disk_counts_network" IN (0, 1)), "ssh_identity_agent" TEXT NULL, PRIMARY KEY ("id"), CHECK (ssh_ip IS NOT NULL OR monitor_addr IS NOT NULL OR is_local = 1), CHECK (ssh_port IS NULL OR ssh_port BETWEEN 1 AND 65535)) WITHOUT ROWID
